package build

import (
	"bytes"
	"errors"
	"fmt"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"

	"go.yaml.in/yaml/v3"

	"github.com/pratik-mahalle/otelkit/internal/model"
	"github.com/pratik-mahalle/otelkit/internal/source"
	"github.com/pratik-mahalle/otelkit/internal/validate"
)

var collectorName = regexp.MustCompile(`(?i)^[a-z0-9._-]*otel[a-z0-9._-]*$`)

// Header starts every generated file.
const Header = "# generated by otelkit from fleet.yaml — do not edit\n"

// Fleet is a parsed fleet.yaml. Paths in it are relative to Dir.
type Fleet struct {
	Dir     string                `yaml:"-"`
	Otelcol string                `yaml:"otelcol"`
	Base    string                `yaml:"base"`
	Targets map[string]TargetSpec `yaml:"targets"`
}

// TargetSpec says what one target is made of.
type TargetSpec struct {
	Fragments []string          `yaml:"fragments,omitempty"`
	Vars      map[string]string `yaml:"vars,omitempty"`
	Overrides string            `yaml:"overrides,omitempty"`
	Output    string            `yaml:"output,omitempty"`
	Deployed  *source.Deployed  `yaml:"deployed,omitempty"`
}

// Load reads fleet.yaml, rejecting unknown fields so typos fail loudly.
func Load(path string) (*Fleet, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	var f Fleet
	if err := dec.Decode(&f); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	if f.Base == "" {
		return nil, fmt.Errorf("%s: base is required", path)
	}
	if f.Otelcol == "" {
		f.Otelcol = "otelcol-contrib"
	}
	// fleet.yaml changes in pull requests, so it may only name a collector on PATH (not a path, not an
	// interpreter that would run a repo file named "validate"); anything else comes from --otelcol
	if !collectorName.MatchString(f.Otelcol) {
		return nil, fmt.Errorf("%s: otelcol must be a collector command name on PATH containing \"otel\"; pass a path with --otelcol", path)
	}
	if f.Dir, err = filepath.Abs(filepath.Dir(path)); err != nil {
		return nil, err
	}
	return &f, nil
}

// Names returns target names sorted.
func (f *Fleet) Names() []string { return slices.Sorted(maps.Keys(f.Targets)) }

// OutputPath is where a target's rendered config is written.
func (f *Fleet) OutputPath(name string) string {
	if out := f.Targets[name].Output; out != "" {
		return filepath.Join(f.Dir, out)
	}
	return filepath.Join(f.Dir, "out", name+".yaml")
}

// Render merges base, fragments and overrides for one target.
func (f *Fleet) Render(name string) (Merged, error) {
	spec, ok := f.Targets[name]
	if !ok {
		return Merged{}, fmt.Errorf("unknown target %q", name)
	}
	type file struct {
		path string
		kind Kind
	}
	files := []file{{f.Base, Base}}
	for _, fr := range spec.Fragments {
		files = append(files, file{filepath.Join("fragments", fr+".yaml"), Fragment})
	}
	if spec.Overrides != "" {
		files = append(files, file{spec.Overrides, Override})
	}
	var layers []Layer
	for _, lf := range files {
		data, err := os.ReadFile(filepath.Join(f.Dir, lf.path))
		if err != nil {
			return Merged{}, fmt.Errorf("%s: %w", lf.path, err)
		}
		root, err := model.Parse(data)
		if err != nil {
			return Merged{}, fmt.Errorf("%s: %w", lf.path, err)
		}
		if err := Substitute(root, spec.Vars, lf.path); err != nil {
			return Merged{}, err
		}
		layers = append(layers, Layer{File: lf.path, Kind: lf.kind, Root: root})
	}
	return Merge(layers)
}

// Bytes is the generated file content: header plus YAML.
func Bytes(root *yaml.Node) ([]byte, error) {
	b, err := model.Marshal(root)
	if err != nil {
		return nil, err
	}
	return append([]byte(Header), b...), nil
}

// Options control a build run.
type Options struct {
	Targets         []string // empty means all
	Check           bool     // render in memory; fail if committed output is stale
	RequireValidate bool     // fail when the otelcol binary is missing
}

// TargetResult is one target's outcome.
type TargetResult struct {
	Name       string
	Output     string
	Warnings   []string
	Validation validate.Result
	Err        error
}

// Run renders, validates and writes targets. One target failing does not stop the others.
func Run(f *Fleet, opt Options) []TargetResult {
	names := opt.Targets
	if len(names) == 0 {
		names = f.Names()
	}
	var out []TargetResult
	for _, name := range names {
		r := TargetResult{Name: name, Output: f.OutputPath(name)}
		r.Err = runTarget(f, opt, &r)
		out = append(out, r)
	}
	return out
}

func runTarget(f *Fleet, opt Options, r *TargetResult) error {
	m, err := f.Render(r.Name)
	if err != nil {
		return err
	}
	r.Warnings = Check(m)
	data, err := Bytes(m.Root)
	if err != nil {
		return err
	}
	// validate a temp copy first so a failing target keeps its previous output
	tmp, err := os.CreateTemp("", "otelkit-*.yaml")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	_, werr := tmp.Write(data)
	if err := errors.Join(werr, tmp.Close()); err != nil {
		return err
	}
	r.Validation = validate.Run(f.Otelcol, f.Dir, tmp.Name())
	switch {
	case r.Validation.Status == validate.Failed:
		return fmt.Errorf("validation failed: %s", r.Validation.Detail)
	case r.Validation.Status == validate.Skipped && opt.RequireValidate:
		return fmt.Errorf("not validated: %s", r.Validation.Detail)
	}
	if opt.Check {
		if old, err := os.ReadFile(r.Output); err != nil || !bytes.Equal(old, data) {
			return fmt.Errorf("%s is stale; run otelkit fleet build", r.Output)
		}
		return nil
	}
	return writeAtomic(r.Output, data)
}

// writeAtomic writes via a temp file + rename so a failure never leaves a half-written config.
func writeAtomic(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".otelkit-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(0o644); err != nil { // CreateTemp makes 0600; the Collector's user must read it
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}
